@sig trait OutcomeReporter_Api {
  def id: Art.BridgeId
  def sessionSnapshot_Id : Art.PortId
  def pilotReport_Id : Art.PortId
  def stationReport_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var pilotReport: Station_Cargo_Transfer_Verification_Supervisor.PilotTransferReport.Type = $

  def put_pilotReport(value : Station_Cargo_Transfer_Verification_Supervisor.PilotTransferReport.Type) : Unit = {
    Contract(
      Modifies(pilotReport),
      Ensures(
        pilotReport == value
      )
    )
    Spec {
      pilotReport = value
    }

    Art.putValue(pilotReport_Id, Station_Cargo_Transfer_Verification_Supervisor.PilotTransferReport_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var stationReport: Station_Cargo_Transfer_Verification_Supervisor.StationTransferReport.Type = $

  def put_stationReport(value : Station_Cargo_Transfer_Verification_Supervisor.StationTransferReport.Type) : Unit = {
    Contract(
      Modifies(stationReport),
      Ensures(
        stationReport == value
      )
    )
    Spec {
      stationReport = value
    }

    Art.putValue(stationReport_Id, Station_Cargo_Transfer_Verification_Supervisor.StationTransferReport_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class OutcomeReporter_Initialization_Api (
  val id: Art.BridgeId,
  val sessionSnapshot_Id : Art.PortId,
  val pilotReport_Id : Art.PortId,
  val stationReport_Id : Art.PortId) extends OutcomeReporter_Api

@datatype class OutcomeReporter_Operational_Api (
  val id: Art.BridgeId,
  val sessionSnapshot_Id : Art.PortId,
  val pilotReport_Id : Art.PortId,
  val stationReport_Id : Art.PortId) extends OutcomeReporter_Api {

  // Logika spec var representing port state for incoming data port
  @spec var sessionSnapshot: Station_Cargo_Transfer_Verification_Supervisor.SessionSnapshot = $

  def get_sessionSnapshot() : Option[Station_Cargo_Transfer_Verification_Supervisor.SessionSnapshot] = {
    Contract(
      Ensures(
        Res == Some(sessionSnapshot)
      )
    )
    val value : Option[Station_Cargo_Transfer_Verification_Supervisor.SessionSnapshot] = Art.getValue(sessionSnapshot_Id) match {
      case Some(Station_Cargo_Transfer_Verification_Supervisor.SessionSnapshot_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port sessionSnapshot.  Expecting 'Station_Cargo_Transfer_Verification_Supervisor.SessionSnapshot_Payload' but received ${v}")
        None[Station_Cargo_Transfer_Verification_Supervisor.SessionSnapshot]()
      case _ => None[Station_Cargo_Transfer_Verification_Supervisor.SessionSnapshot]()
    }
    return value
  }
}
